{
    "friendly_name": "owl_scene_1_sale",
    "language": "en",
    "variables": {
        "name": "Twill",
        "discount": "30"
    },
    "types": {
        "twilio/card": {
            "title": "Early access to Owl Sale",
            "body": "Hi {{name}}, we have curated items for you from our annual sale starting tomorrow.\n\nGet {{discount}}% discount for early orders as our VIP customer! Order now!",
            "media": [
                "https://forge-assets-5378.twil.io/owl_store/rich-card-sales.jpg"
            ],
            "actions": [
                {
                    "type": "QUICK_REPLY",
                    "title": "Show products",
                    "id": "btn-show-products"
                },
                {
                    "type": "QUICK_REPLY",
                    "title": "Send coupon code",
                    "id": "btn-send-coupon"
                }
            ]
        },
        "twilio/text": {
            "body": "Hi {{name}}, we have curated items for you from our annual sale starting tomorrow.\n\nGet {{discount}}% discount for early orders as our VIP customer! Order now!\n\n---\n\nReply 1 to see products\nReply 2 for get your discount code"
        }
    }
}

{
    "friendly_name": "owl_scene_2_products",
    "language": "en",
    "variables": {},
    "types": {
        "twilio/carousel": {
            "body": "Which ones do you like?",
            "cards": [
                {
                    "title": "Owl-Red Printed Hoodie",
                    "body": "A comfy hoodie in our signature colour!",
                    "media": "https://forge-assets-5378.twil.io/owl_store/rich-card-hoodie-lifestyle-1.jpg",
                    "actions": [
                        {
                            "type": "QUICK_REPLY",
                            "title": "Add to bag",
                            "id": "btn-add-hoodie"
                        },
                        {
                            "type": "QUICK_REPLY",
                            "title": "Show more photos",
                            "id": "btn-show-more-hoodie"
                        }
                    ]
                },
                {
                    "title": "Shoes to flaunt",
                    "body": "Owl-Red and Owl branded shoes to show-off on-stage!",
                    "media": "https://forge-assets-5378.twil.io/owl_store/carousel-shoes-front.jpg",
                    "actions": [
                        {
                            "type": "QUICK_REPLY",
                            "title": "Add to bag",
                            "id": "btn-add-shoes"
                        },
                        {
                            "type": "QUICK_REPLY",
                            "title": "Show more photos",
                            "id": "btn-show-more-shoes"
                        }
                    ]
                }
            ]
        },
        "twilio/text": {
            "body": "Reply 1 for Owl-Red Comfy Hoodies\n\nReply 2 for Owl-Red branded Shoes"
        }
    }
}

{
    "friendly_name": "owl_scene_3_delivery",
    "language": "en",
    "variables": {
        "name": "Twill",
        "store_name": "Owl Store SIGNAL",
        "store_address": "101 Spear St 5th floor, San Francisco, CA 94105",
        "url": "https://maps.app.goo.gl/QUf1dE2XiDrZCdg67"
    },
    "types": {
        "twilio/card": {
            "title": "🎉 Order confirmed! Choose delivery.",
            "body": "Pickup from our nearest store, or opt for doorstep delivery",
            "media": [
                "https://forge-assets-5378.twil.io/owl_store/owl-ops-complete.png"
            ],
            "actions": [
                {
                    "type": "URL",
                    "id": "btn_3_directions",
                    "title": "Store pick-up",
                    "url": "{{url}}"
                },
                {
                    "type": "QUICK_REPLY",
                    "id": "btn_3_deliver",
                    "title": "Doorstep delivery",
                    "url": "{{directions_url}}"
                }
            ]
        },
        "twilio/text": {
            "body": "Pickup from our nearest store, or opt for doorstep delivery.\n\nNearest store: {{url}}\n\n---\n\nReply '1' for pickup at store.\n\nReply '2' for doorstep delivery."
        }
    }
}
